--!nocheck
-- Карты способностей (150 шт., по каталогу оригинала).
--
-- Поля карты:
--   id     — номер из оригинала
--   r      — редкость: n (обычная), r (редкая), sr (легендарная)
--   s      — стили (1-2)
--   name   — русское название
--   desc   — описание; {v}, {v2} подставляются значениями текущей звезды
--   v, v2  — значения по звёздам. 5 чисел = по звезде; 3 числа (как у
--            редких в оригинале) раскладываются на 5 звёзд интерполяцией;
--            1 число = одинаково на всех звёздах.
--   fx     — список эффектов (DSL, исполняется Combat/Effects):
--     {k="stat", stat=..., key="v"|val=N}      постоянный стат
--     {k="statXp", stat=..., style=..., key="v2"} стат за каждый XP стиля
--     {k="on", ev=..., chance=N, cdKey=..., a=ACTION}  реакция на событие
--     {k="every", t=N|tKey=..., a=ACTION}       периодический эффект
--     {k="hpLoss", per=N, a=ACTION}             за каждые N потерянного HP
--     {k="healAccum", per=N, a=ACTION}          за каждые N вылеченного HP
--     {k="start", a=ACTION}                     в начале боя
--     {k="below", pct=N, a=ACTION}              один раз при HP ниже N%
--     {k="ward", a=ACTION}                      каждый срабатывающий страж
--     {k="wardDeath", a=ACTION}                 смерть своего стража
--     {k="special", id=...}                     особая логика в коде
--   События ev: attack, crit, evade, heal, ult, poison, ice, injury,
--     shieldGain, furyGain, damaged, dealDamage, shieldBlock.
--   ACTION: {"heal"}, {"mana"}, {"poison"}, {"ice"}, {"injury"}, {"shield"},
--     {"fury"}, {"perm", s=...}, {"dmg", t=...}, {"ult"}, {"attack"},
--     {"buff", stat, val, dur, maxKey}, {"grow", stat, maxKey}, ...
--     Значение действия по умолчанию берётся из v (или key/val).

local function on(ev, chance, a, extra)
	local e = { k = "on", ev = ev, chance = chance, a = a }
	if extra then
		for key, value in pairs(extra) do
			e[key] = value
		end
	end
	return e
end
local function stat(name, key) return { k = "stat", stat = name, key = key or "v" } end
local function statVal(name, val) return { k = "stat", stat = name, val = val } end
local function statXp(name, style) return { k = "statXp", stat = name, style = style, key = "v2" } end
local function every(t, a) return { k = "every", t = t, a = a } end
local function hpLoss(per, a) return { k = "hpLoss", per = per, a = a } end
local function start(a) return { k = "start", a = a } end
local function below(pct, a) return { k = "below", pct = pct, a = a } end
local function ward(a) return { k = "ward", a = a } end
local function special(id) return { k = "special", id = id } end

